/*
 * Gemmi idle animation on a white screen, decoded live by LVGL's GIF widget.
 * Tapping anywhere plays a random reaction animation, then returns to idle.
 * GIF data lives in gemmi_anims.c (generated by tools/gifs_to_carray.py).
 */
#include "lvgl.h"
#include "esp_timer.h"
#include "gemmi_anims.h"

static lv_obj_t *gif;
static lv_timer_t *idle_timer;

static void back_to_idle(lv_timer_t *t)
{
    LV_UNUSED(t);
    lv_gif_set_src(gif, gemmi_anims[GEMMI_ANIM_IDLE].dsc);
    idle_timer = NULL;
}

static void on_tap(lv_event_t *e)
{
    LV_UNUSED(e);
    uint32_t n = 1 + (uint32_t)esp_timer_get_time() % (gemmi_anims_count - 1);
    lv_gif_set_src(gif, gemmi_anims[n].dsc);

    if(idle_timer) lv_timer_delete(idle_timer);
    idle_timer = lv_timer_create(back_to_idle, gemmi_anims[n].total_ms, NULL);
    lv_timer_set_repeat_count(idle_timer, 1);
}

void example_lvgl_demo_ui(lv_display_t *disp)
{
    lv_obj_t *scr = lv_display_get_screen_active(disp);
    lv_obj_set_style_bg_color(scr, lv_color_white(), LV_PART_MAIN | LV_STATE_DEFAULT);

    gif = lv_gif_create(scr);
    lv_gif_set_color_format(gif, LV_COLOR_FORMAT_ARGB8888);
    lv_gif_set_src(gif, gemmi_anims[GEMMI_ANIM_IDLE].dsc);
    lv_image_set_scale(gif, 512);   /* 256 = 100%, so 512 = 2x (192x192) */
    lv_obj_center(gif);

    lv_obj_add_flag(scr, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_event_cb(scr, on_tap, LV_EVENT_CLICKED, NULL);
}
